function txt(p,s,o={}){const t=figma.createText();t.fontName={family:o.fam||'Tenor Sans',style:o.sty||'Regular'};t.characters=String(s);t.fontSize=o.size||14;t.fills=[{type:'SOLID',color:hex(o.color||'333333')}];t.letterSpacing={unit:'PIXELS',value:o.ls||0};t.lineHeight={unit:'PIXELS',value:o.lh||Math.round((o.size||14)*1.45)};t.x=o.x||0;t.y=o.y||0;if(o.w){t.textAutoResize='HEIGHT';t.resize(o.w,10);}if(o.align)t.textAlignHorizontal=o.align;p.appendChild(t);return t;}
function rect(p,x,y,w,h,color,r=0){const q=figma.createRectangle();q.resize(w,h);q.x=x;q.y=y;q.fills=[{type:'SOLID',color:hex(color)}];if(r)q.cornerRadius=r;p.appendChild(q);return q;}
async function ico(p,id,x,y,s=24){const n=await figma.getNodeByIdAsync(id);const i=n.createInstance();i.resize(s,s);i.x=x;i.y=y;p.appendChild(i);return i;}
async function img(p,id,x,y,w,h){const n=await figma.getNodeByIdAsync(id);const i=n.createInstance();i.resize(w,h);i.x=x;i.y=y;p.appendChild(i);return i;}
